class Solution {
public:
    int kConcatenationMaxSum(std::vector<int>& arr, int k) {
        long long MOD = 1e9 + 7;
        auto kadane = [](const std::vector<int>& nums) -> long long {
            long long cur = 0, best = 0;
            for (int x : nums) {
                cur = std::max(0LL, cur + x);
                best = std::max(best, cur);
            }
            return best;
        };

        long long total = 0;
        for (int x : arr) total += x;

        if (k == 1) return kadane(arr) % MOD;

        std::vector<int> twoArr = arr;
        twoArr.insert(twoArr.end(), arr.begin(), arr.end());
        long long maxTwo = kadane(twoArr);

        if (total > 0) {
            return (maxTwo + (k - 2LL) * total) % MOD;
        }
        return maxTwo % MOD;
    }
};

class Solution {
    long kadane(int[] nums, int repeat) {
        long cur = 0, best = 0;
        for (int r = 0; r < repeat; r++) {
            for (int x : nums) {
                cur = Math.max(0, cur + x);
                best = Math.max(best, cur);
            }
        }
        return best;
    }

    public int kConcatenationMaxSum(int[] arr, int k) {
        long MOD = 1_000_000_007L;
        long total = 0;
        for (int x : arr) total += x;

        if (k == 1) return (int) (kadane(arr, 1) % MOD);

        long maxTwo = kadane(arr, 2);
        if (total > 0) {
            return (int) ((maxTwo + (k - 2L) * total) % MOD);
        }
        return (int) (maxTwo % MOD);
    }
}

var kConcatenationMaxSum = function(arr, k) {
    const MOD = 1000000007n;
    const kadane = (repeat) => {
        let cur = 0n, best = 0n;
        for (let r = 0; r < repeat; r++) {
            for (const x of arr) {
                cur = cur + BigInt(x);
                if (cur < 0n) cur = 0n;
                if (cur > best) best = cur;
            }
        }
        return best;
    };

    let total = 0n;
    for (const x of arr) total += BigInt(x);

    if (k === 1) return Number(kadane(1) % MOD);

    const maxTwo = kadane(2);
    if (total > 0n) {
        return Number((maxTwo + BigInt(k - 2) * total) % MOD);
    }
    return Number(maxTwo % MOD);
};
